import {createTrack,Race,STEP,PAINTS,clamp,angleDiff,resetCar,validateProfile,updateRecords} from './sim.js';
import {World} from './world.js';
import {Sound} from './audio.js';
const $=id=>document.getElementById(id),track=createTrack(),race=new Race(track),sound=new Sound();let profile;try{profile=validateProfile(JSON.parse(localStorage.getItem('harbor-run-v1')));}catch{profile=validateProfile(null);}let world,ready=false,last=performance.now(),accumulator=0,resultShown=false,padButtons=[],keys=new Set(),lastPad=null;
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const format=t=>{if(!Number.isFinite(t))return '—';const ms=Math.floor(Math.max(0,t)*1000);return String(Math.floor(ms/60000)).padStart(2,'0')+':'+String(Math.floor(ms/1000)%60).padStart(2,'0')+'.'+String(ms%1000).padStart(3,'0');};
const save=()=>{try{localStorage.setItem('harbor-run-v1',JSON.stringify(profile));}catch{}};
const show=id=>{for(const name of ['menu','loading','hud','pause','results','error'])$(name).hidden=name!==id;if(id==='pause')$('hud').hidden=false;};
const refreshBest=()=>{$('menuBest').textContent='BEST LAP '+format(profile.records.lap);$('bestLap').textContent='BEST '+format(profile.records.lap);};
$('trackLength').textContent=(track.length/1000).toFixed(1);$('quality').value=profile.quality;$('volume').value=profile.volume;sound.volume=profile.volume;refreshBest();
PAINTS.forEach((color,i)=>{const btn=document.createElement('button');btn.style.setProperty('--paint',color);btn.setAttribute('aria-label',['Carmine red','Pearl ivory','Graphite','Harbor blue'][i]);btn.setAttribute('aria-pressed',color===profile.paint);btn.onclick=()=>{profile.paint=color;race.player.color=color;world?.setPaint(color);save();for(const child of $('paints').children)child.setAttribute('aria-pressed',child===btn);};$('paints').append(btn);});
function openDetails(name){for(const id of ['controls','settings','credits'])$(id+'Content').hidden=id!==name;$('details').showModal();$('closeDetails').focus();}
for(const name of ['controls','settings','credits'])$(name+'Button').onclick=()=>openDetails(name);$('closeDetails').onclick=()=>$('details').close();
$('quality').onchange=()=>{profile.quality=$('quality').value;world?.setQuality(profile.quality);save();};$('volume').oninput=()=>{profile.volume=Number($('volume').value);sound.volume=profile.volume;save();};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{}};
function start(){if(!ready||$('details').open)return;race.restart(profile.paint);world.attachCars();resultShown=false;accumulator=0;keys.clear();show('hud');sound.resume().catch(()=>{});}
function garage(){race.phase='menu';keys.clear();refreshBest();show('menu');$('start').focus();}
function pause(){if(!ready||!['countdown','racing','paused'].includes(race.phase))return;race.pause();keys.clear();accumulator=0;if(race.phase==='paused'){show('pause');$('resume').focus();}else{show('hud');sound.resume().catch(()=>{});}}
$('start').onclick=start;$('resume').onclick=pause;$('pauseButton').onclick=pause;$('restartPause').onclick=start;$('raceAgain').onclick=start;$('exitPause').onclick=garage;$('exitResults').onclick=garage;$('retry').onclick=()=>location.reload();
const inputKeys=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','ShiftLeft','ShiftRight','KeyQ','KeyC','KeyR','Escape'];
addEventListener('keydown',e=>{if($('details').open)return;if(inputKeys.includes(e.code)&&['racing','countdown','paused'].includes(race.phase))e.preventDefault();if(e.code==='Escape'&&!e.repeat){pause();return;}if(e.code==='Enter'&&race.phase==='menu'){e.preventDefault();start();return;}if(e.code==='KeyR'&&!e.repeat&&race.phase==='racing'){resetCar(race.player,track);world.followInitialized=false;return;}keys.add(e.code);});addEventListener('keyup',e=>keys.delete(e.code));
const blur=()=>{keys.clear();if(['racing','countdown'].includes(race.phase))pause();};addEventListener('blur',blur);document.addEventListener('visibilitychange',()=>{if(document.hidden)blur();});addEventListener('gamepaddisconnected',()=>{lastPad=null;padButtons=[];blur();});addEventListener('resize',()=>world?.resize());
function readInput(){const pressed=(...codes)=>codes.some(c=>keys.has(c));const input={throttle:+pressed('KeyW','ArrowUp'),brake:+pressed('KeyS','ArrowDown'),steer:+pressed('KeyD','ArrowRight')-+pressed('KeyA','ArrowLeft'),handbrake:pressed('Space'),boost:pressed('ShiftLeft','ShiftRight'),breaker:pressed('KeyQ'),rear:pressed('KeyC')};const pads=navigator.getGamepads?.()??[],pad=Array.from(pads).find(p=>p&&p.mapping==='standard');if(pad){if(lastPad!==pad.index){lastPad=pad.index;padButtons=[];}const b=i=>pad.buttons[i]?.value??0,edge=i=>b(i)>.5&&!padButtons[i];if(edge(9)){if(race.phase==='menu'||race.phase==='finished')start();else pause();}if(edge(3)&&race.phase==='racing'){resetCar(race.player,track);world.followInitialized=false;}if(['racing','countdown'].includes(race.phase)){input.throttle=Math.max(input.throttle,b(7));input.brake=Math.max(input.brake,b(6));const axis=pad.axes[0]??0;if(Math.abs(axis)>.1)input.steer=clamp((Math.abs(axis)-.1)/.9,0,1)*Math.sign(axis);input.handbrake ||=b(0)>.5;input.boost ||=b(1)>.5;input.breaker ||=b(2)>.5;input.rear ||=b(5)>.5;}padButtons=pad.buttons.map(b=>b.value>.5);}return input;}
const map=$('map').getContext('2d'),bounds=track.samples.reduce((b,p)=>({minX:Math.min(b.minX,p.x),minZ:Math.min(b.minZ,p.z),maxX:Math.max(b.maxX,p.x),maxZ:Math.max(b.maxZ,p.z)}),{minX:Infinity,minZ:Infinity,maxX:-Infinity,maxZ:-Infinity});const scale=Math.min(180/(bounds.maxX-bounds.minX),150/(bounds.maxZ-bounds.minZ));const mapPoint=p=>[20+(p.x-bounds.minX)*scale,170-(p.z-bounds.minZ)*scale];
for(let i=0;i<=24;i++){const angle=(-140+i/24*280)*Math.PI/180,x=125+Math.sin(angle)*93,y=125-Math.cos(angle)*93,inner=i%4===0?82:88;const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',x);line.setAttribute('y1',y);line.setAttribute('x2',125+Math.sin(angle)*inner);line.setAttribute('y2',125-Math.cos(angle)*inner);$('ticks').append(line);}
function drawMap(){map.clearRect(0,0,220,190);map.beginPath();track.samples.forEach((p,i)=>{const [x,y]=mapPoint(p);i?map.lineTo(x,y):map.moveTo(x,y);});map.strokeStyle='#07151acf';map.lineWidth=10;map.stroke();map.strokeStyle='#d7dfcd80';map.lineWidth=3;map.stroke();const start=mapPoint(track.at(0));map.fillStyle='#efc34d';map.fillRect(start[0]-3,start[1]-3,6,6);for(const car of [...race.rivals,race.player]){const [x,y]=mapPoint(car);map.beginPath();map.arc(x,y,car===race.player?4.2:3,0,Math.PI*2);map.fillStyle=car===race.player?'#efc34d':'#e0e4e5';map.fill();}}
function finish(){resultShown=true;const old=profile.records.race;updateRecords(profile,race.player);save();refreshBest();$('resultHeadline').textContent=race.position===1?'The city is yours.':'Across the line.';$('resultSummary').textContent='Finished '+['1st','2nd','3rd','4th'][race.position-1]+' of 4 racers.';$('resultTime').textContent=format(race.player.finish);$('resultLap').textContent=format(Math.min(...race.player.lapTimes));$('recordMessage').textContent=(!old||race.player.finish<old)?'NEW PERSONAL BEST':'Best race '+format(profile.records.race);$('standings').replaceChildren();race.standings.forEach((car,i)=>{const li=document.createElement('li');const name=document.createElement('span'),time=document.createElement('span');name.textContent=(i+1)+'. '+car.name;time.textContent=car.finish!==null?format(car.finish):'On circuit';li.append(name,time);$('standings').append(li);});show('results');$('raceAgain').focus();}
function hud(){const c=race.player,kmh=Math.round(Math.abs(c.speed)*3.6);$('position').textContent=race.position;$('lap').textContent=c.lap;$('speed').textContent=kmh;$('gear').textContent=c.speed<-.5?'R':c.speed<1?'N':clamp(Math.floor(c.speed/12)+1,1,6);$('raceTime').textContent=format(race.elapsed);$('lapTime').textContent=format(race.elapsed-c.lapStart);$('nitro').value=c.nitrous;$('breaker').value=c.breaker;$('gaugeFill').style.strokeDasharray=clamp(kmh/280*100,0,100)+' 100';$('raceMessage').textContent=race.phase==='countdown'?Math.ceil(race.countdown):race.phase==='racing'&&race.elapsed<.75?'GO':'';$('wrongWay').hidden=race.phase!=='racing'||c.speed<3||Math.abs(angleDiff(c.heading,track.at(c.s).heading))<1.8;$('breakerTint').style.opacity=c.breakingTime&&race.phase==='racing'?1:0;drawMap();}
function fail(error){ready=false;show('error');$('errorText').textContent=error?.message?.includes('WebGL')?'This browser could not initialize WebGL. Use a browser with hardware acceleration, then reload.':'The 3D assets could not load or the graphics context stopped. Reload to try again.';console.error('Harbor Run:',error);}
async function boot(){try{world=new World($('world'),track,race);world.setQuality(profile.quality);race.player.color=profile.paint;await world.load(p=>{$('loadProgress').value=p;$('loadingText').textContent=p<.28?'Loading road textures and daylight…':p<.75?'Loading detailed city scenery…':'Loading detailed sports car…';});ready=true;show('menu');$('start').focus();window.harborRun={race,track,world,profile,version:'1.2.0'};$('world').addEventListener('webglcontextlost',e=>{e.preventDefault();blur();fail(new Error('WebGL context lost'));});}catch(error){fail(error);}}
function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;if(ready){const input=readInput();accumulator+=dt;let count=0;while(accumulator>=STEP&&count<8){race.step(input,STEP);accumulator-=STEP;count++;}if(race.phase==='finished'&&!resultShown)finish();if(['racing','countdown','paused'].includes(race.phase))hud();sound.update(race.player,race.phase==='racing');try{world.update(dt,input.rear,race.phase==='menu',reducedMotion);}catch(error){fail(error);}}requestAnimationFrame(frame);}boot();requestAnimationFrame(frame);
